    public void init() {
        try {
            // 1. Load the native library
            ZLM_API = Native.load("zlm_api", ZLMApi.class);

            // 2. Initialize the environment using the configuration
            // Using mk_env_init1 as it provides detailed control over logging and threads
            ZLM_API.mk_env_init1(
                    config.getThread_num(),
                    config.getLog_level(),
                    config.getLog_mask(),
                    config.getLog_path(),
                    config.getLog_file_days(),
                    0, // ini_is_path: 0 means the next parameter is the content string, not a path
                    null, // ini: passing null to use default or set options later
                    0, // ssl_is_path: 0 means no SSL or next is content
                    null, // ssl
                    null  // ssl_pwd
            );

            // 3. Start the various servers based on configuration
            if (config.getEnable_http() != null && config.getEnable_http() == 1) {
                ZLM_API.mk_http_server_start(config.getHttp_port().shortValue(), 0);
            }
            if (config.getEnable_rtmp() != null && config.getEnable_rtmp() == 1) {
                ZLM_API.mk_rtmp_server_start(config.getRtmp_port().shortValue(), 0);
            }
            if (config.getEnable_rtsp() != null && config.getEnable_rtsp() == 1) {
                ZLM_API.mk_rtsp_server_start(config.getRtsp_port().shortValue(), 0);
            }

            // 4. Initialize and register global events
            MK_EVENTS = new MK_EVENTS();
            // Here you would typically assign the callback implementations from your callback package
            // Example: MK_EVENTS.on_mk_media_publish = (url_info, invoker, sender) -> { ... };
            ZLM_API.mk_events_listen(MK_EVENTS);

            log.info("Media Server initialized successfully.");
        } catch (Exception e) {
            log.error("Failed to initialize Media Server: {}", e.getMessage(), e);
        }
    }

    @PreDestroy
    public void destroy() {
        if (ZLM_API != null) {
            ZLM_API.mk_stop_all_server();
            log.info("Media Server stopped.");
        }
    }
}
