    public void applyResetPassword(ApplyResetPasswordDto applyResetPasswordDto, HttpServletRequest request) throws StatusFailException {
        // 验证验证码
        if (StringUtils.isEmpty(applyResetPasswordDto.getCaptchaKey()) || StringUtils.isEmpty(applyResetPasswordDto.getCaptcha())) {
            throw new StatusFailException("验证码不能为空");
        }
        // 这里假设有一个验证码验证逻辑，通常是通过 redisUtils 校验 captchaKey 和 captcha
        // if (!captchaService.verify(applyResetPasswordDto.getCaptchaKey(), applyResetPasswordDto.getCaptcha())) {
        //     throw new StatusFailException("验证码错误");
        // }

        String email = applyResetPasswordDto.getEmail();
        if (StringUtils.isEmpty(email)) {
            throw new StatusFailException("邮箱不能为空");
        }
        email = email.trim();
        if (!Validator.isEmail(email)) {
            throw new StatusFailException("邮箱格式不正确");
        }

        // 检查邮箱是否在黑名单中
        boolean isBlackEmail = emailRuleBo.getBlackList().stream().anyMatch(email::endsWith);
        if (isBlackEmail) {
            throw new StatusForbiddenException("对不起！您的邮箱无法注册本网站！");
        }

        // 频率限制
        String lockKey = Constants.Email.RESET_EMAIL_LOCK + email;
        if (redisUtils.hasKey(lockKey)) {
            throw new StatusFailException("对不起，您的操作频率过快，请在" + redisUtils.getExpire(lockKey) + "秒后再次发送重置密码邮件！");
        }

        // 检查用户是否存在
        QueryWrapper<UserInfo> queryWrapper = new QueryWrapper<>();
        queryWrapper.eq("email", email);
        UserInfo userInfo = userInfoEntityService.getOne(queryWrapper, false);
        if (userInfo == null) {
            throw new StatusFailException("该邮箱未注册");
        }

        // 生成重置密码的随机码 (20位数字与字母组合)
        String code = RandomUtil.randomAlphanumeric(20);
        // 存储到Redis，有效期10分钟
        redisUtils.set(Constants.Email.RESET_PASSWORD_KEY_PREFIX.getValue() + userInfo.getUid(), code, 10 * 60);

        // 发送邮件
        emailManager.sendResetPassword(userInfo.getUsername(), code, email);

        // 设置频率锁，60秒
        redisUtils.set(lockKey, 0, 60);
    }

    @Transactional(rollbackFor = Exception.class)
    public void resetPassword(ResetPasswordDto resetPasswordDto) throws StatusFailException {
        if (StringUtils.isEmpty(resetPasswordDto.getUsername()) || StringUtils.isEmpty(resetPasswordDto.getCode())) {
            throw new StatusFailException("参数不能为空");
        }

        // 根据用户名获取用户信息
        QueryWrapper<UserInfo> queryWrapper = new QueryWrapper<>();
        queryWrapper.eq("username", resetPasswordDto.getUsername());
        UserInfo userInfo = userInfoEntityService.getOne(queryWrapper, false);
        if (userInfo == null) {
            throw new StatusFailException("用户不存在");
        }

        // 校验重置码
        String codeKey = Constants.Email.RESET_PASSWORD_KEY_PREFIX.getValue() + userInfo.getUid();
        if (!redisUtils.hasKey(codeKey)) {
            throw new StatusFailException("重置链接已过期");
        }
        if (!redisUtils.get(codeKey).equals(resetPasswordDto.getCode())) {
            throw new StatusFailException("重置码不正确");
        }

        // 校验新密码
        String newPassword = resetPasswordDto.getPassword();
        if (StringUtils.isEmpty(newPassword) || newPassword.length() < 6 || newPassword.length() > 20) {
            throw new StatusFailException("新密码长度应在6~20位之间");
        }

        // 更新密码
        UserInfo updateUserInfo = new UserInfo();
        updateUserInfo.setUid(userInfo.getUid());
        updateUserInfo.setPassword(SecureUtil.md5(newPassword.trim()));
        userInfoEntityService.updateById(updateUserInfo);

        // 删除重置码
        redisUtils.del(codeKey);
    }
