    public void generateData(Map<JurorStatus, Integer> jurorStatusCountMap, boolean isCourtOwned) {
        stopWatch.start();

        // 1. Clear existing data
        jurorRepository.truncateTable();
        jurorPoolRepository.truncateTable();
        poolRequestRepository.truncateTable();
        digitalResponseRepository.truncateTable();
        paperResponseRepository.truncateTable();

        // 2. Generate Pool Requests (needed for JurorPool assignment)
        List<PoolRequest> poolRequests = new ArrayList<>();
        // Using the weighted map from Constants to create a diverse set of pools
        Constants.POOL_REQUEST_WEIGHT_MAP.forEach((type, weight) -> {
            for (int i = 0; i < weight / 100; i++) { // Simplified scaling for example
                poolRequests.add(PoolRequestGeneratorUtil.create(isCourtOwned, type).generate());
            }
        });
        Util.batchSave(poolRequestRepository, poolRequests, BATCH_SIZE);

        // 3. Create Juror Account Details (Jurors, Pools, and Responses)
        List<JurorAccountDetailsDto> jurorAccountDetailsDtos = createJurorAccountDetailsDtos(isCourtOwned, jurorStatusCountMap);

        // 4. Save Jurors
        Util.batchSave(jurorRepository, 
            jurorAccountDetailsDtos.stream().map(JurorAccountDetailsDto::getJuror).toList(), 
            BATCH_SIZE);

        // 5. Save Responses (Digital and Paper)
        List<AbstractJurorResponse> responses = jurorAccountDetailsDtos.stream()
            .map(JurorAccountDetailsDto::getJurorResponse)
            .filter(java.util.Objects::nonNull)
            .toList();

        List<DigitalResponse> digitalResponses = responses.stream()
            .filter(r -> r instanceof DigitalResponse)
            .map(r -> (DigitalResponse) r)
            .toList();
        List<PaperResponse> paperResponses = responses.stream()
            .filter(r -> r instanceof PaperResponse)
            .map(r -> (PaperResponse) r)
            .toList();

        Util.batchSave(digitalResponseRepository, digitalResponses, BATCH_SIZE);
        Util.batchSave(paperResponseRepository, paperResponses, BATCH_SIZE);

        // 6. Save Juror Pools
        Util.batchSave(jurorPoolRepository,
            jurorAccountDetailsDtos.stream().map(JurorAccountDetailsDto::getJurorPools).flatMap(List::stream).toList(),
            BATCH_SIZE);

        stopWatch.stop();
    }

