    if (jfinalConfig == null) {
      throw new RuntimeException("JFinalConfig bean not found. Please provide a JFinalConfig bean.");
    }
    jfinal.init(jfinalConfig, servletContext);
    long serverEndTime = System.currentTimeMillis();

