    JFinalHttpRequestHandler jfinalHttpRequestHandler = new JFinalHttpRequestHandler(httpConfig, new DefaultHttpServerInterceptor());
    jfinalHttpRequestHandler.setHandler(jfinal.getHandler());
    long configEndTimeTime = System.currentTimeMillis();

    long routeStartTime = System.currentTimeMillis();
    // 4. Start TIO Server
    ServerTioConfig serverTioConfig = Aop.get(ServerTioConfig.class);
    tioBootServer = new TioBootServer(serverTioConfig);

    TioBootServerHandler serverHandler = new TioBootServerHandler(
