    tioBootServer.getTioServer().setConfig(serverTioConfig);
    tioBootServer.getTioServer().setServerAioHandler(serverHandler);
    tioBootServer.getTioServer().setServerAioListener(serverListener);

    try {
      tioBootServer.start(serverTioConfig.getServerIp(), serverTioConfig.getServerPort());
    } catch (IOException e) {
      log.error(e.toString(), e);
    }

      jfinalConfig.onStart();
