    @Nullable
    public Object go(Context context, Card card, int requestCode, ActivityResultLauncher<Intent> launcher, GoCallback callback) {
        // 1. 预处理
        card.setContext(context);
        IPretreatmentService pretreatmentService = getService(IPretreatmentService.class);
        if (pretreatmentService != null && !pretreatmentService.onPretreatment(context, card)) {
            return null;
        }

        // 2. 组装路由元数据
        try {
            RouteCenter.assembleRouteCard(card);
        } catch (NoFoundRouteException e) {
            GoCallback finalCallback = callback != null ? callback : new GoCallback() {
                @Override public void onFound(Card card) {}
                @Override public void onLost(Card card) {
                    IDegradeService degradeService = getService(IDegradeService.class);
                    if (degradeService != null) degradeService.onLost(context, card);
                }
                @Override public void onArrival(Card card) {}
                @Override public void onInterrupt(Card card, Throwable exception) {}
            };
            finalCallback.onLost(card);
            return null;
        }

        // 3. 拦截器处理
        if (card.isGreenChannel()) {
            return executeGo(context, card, requestCode, launcher, callback);
        }

        IInterceptorService interceptorService = getService(IInterceptorService.class);
        if (interceptorService != null) {
            interceptorService.doInterceptions(card, new InterceptorCallback() {
                @Override
                public void onContinue(Card card) {
                    executeGo(context, card, requestCode, launcher, callback);
                }

                @Override
                public void onInterrupt(Card card, Throwable exception) {
                    if (callback != null) {
                        callback.onInterrupt(card, exception);
                    }
                }
            });
            return null;
        } else {
            return executeGo(context, card, requestCode, launcher, callback);
        }
    }

    @Nullable
    private Object executeGo(Context context, Card card, int requestCode, ActivityResultLauncher<Intent> launcher, GoCallback callback) {
        CardMeta meta = card.getCardMeta();
        if (meta == null) return null;

        try {
            Object target = meta.getPathClass().getConstructor().newInstance();
            Intent intent = new Intent(context, meta.getPathClass());
            intent.putExtras(card.getExtras());

            if (meta.getType() == RouteType.Activity) {
                if (launcher != null) {
                    launcher.launch(intent);
                } else {
                    ActivityCompat.startActivityForResult(context, intent, requestCode);
                }
            } else if (meta.getType() == RouteType.Fragment) {
                // Fragment logic would go here
            }

            if (callback != null) {
                callback.onFound(card);
                callback.onArrival(card);
            }
            return target;
        } catch (Exception e) {
            if (callback != null) {
                callback.onInterrupt(card, e);
            }
            return null;
        }
    }
}
