    private void checkLogin(LoginType loginType, String username, Supplier<Boolean> checkSupplier) {
        if (checkSupplier.get()) {
            String key = CacheConstants.PWD_ERR_CNT_KEY + username;
            long count = RedisUtils.incrAtomicValue(key);
            if (count == 1) {
                RedisUtils.expire(key, Duration.ofHours(24));
            }
            if (count >= maxRetryCount) {
                recordLogininfor(username, Constants.LOGIN_FAIL, MessageUtils.message(loginType.getRetryLimitExceed()));
                throw new UserException(loginType.getRetryLimitExceed(), username);
            }
            recordLogininfor(username, Constants.LOGIN_FAIL, MessageUtils.message(loginType.getRetryLimitCount(), count));
            throw new UserException("user.password.error", username);
        }
    }

