    private void applyGiveMoney() {
        List<ActionGiveMoney> moneyActions = new ArrayList<>();
        String query = String.format("SELECT * FROM give_money WHERE server != '%s'", server);
        try (PreparedStatement preparedStatement = connection.prepareStatement(query);
             ResultSet resultSet = preparedStatement.executeQuery()) {
            while (resultSet.next()) {
                moneyActions.add(ActionGiveMoney.fromResultSet(resultSet));
            }
        } catch (SQLException e) {
            Main.getMessage().error(e);
        }

        for (ActionGiveMoney action : moneyActions) {
            OfflinePlayer offlinePlayer = Bukkit.getOfflinePlayer(action.getUuid());
            Main.getEcon().depositPlayer(offlinePlayer, action.getCount());
            try (PreparedStatement deleteStatement = connection.prepareStatement("DELETE FROM give_money WHERE uuid = ? AND count = ? AND server = ?")) {
                deleteStatement.setObject(1, action.getUuid());
                deleteStatement.setDouble(2, action.getCount());
                deleteStatement.setString(3, action.getServer());
                deleteStatement.executeUpdate();
            } catch (SQLException e) {
                Main.getMessage().error("failed to remove give_money record", e);
            }
        }
    }
```

