            menuVO.setName(menuDTO.getTitle());
            menuVO.setPath(menuDTO.getPath());
            menuVO.setComponent(menuDTO.getComponent());
            menuVO.setHidden(menuDTO.getHidden());

            MenuMetaVO meta = new MenuMetaVO();
            meta.setTitle(menuDTO.getTitle());
            meta.setIcon(menuDTO.getIcon());
            meta.setNoCache(!menuDTO.getCache());
            menuVO.setMeta(meta);

            if (menuDTO.getChildren() != null && !menuDTO.getChildren().isEmpty()) {
                List<MenuVO> children = new ArrayList<>();
                for (MenuDTO childDTO : menuDTO.getChildren()) {
                    // This is a simplified recursive call logic usually handled by a helper method
                    // but following the pattern of buildTree and MenuVO structure:
                    children.add(convertDtoToVo(childDTO));
