    private MenuVO convertDtoToVo(MenuDTO dto) {
        MenuVO vo = new MenuVO();
        vo.setName(dto.getTitle());
        vo.setPath(dto.getPath());
        vo.setComponent(dto.getComponent());
        vo.setHidden(dto.getHidden());

        MenuMetaVO meta = new MenuMetaVO();
        meta.setTitle(dto.getTitle());
        meta.setIcon(dto.getIcon());
        meta.setNoCache(!dto.getCache());
        vo.setMeta(meta);

        if (dto.getChildren() != null && !dto.getChildren().isEmpty()) {
            vo.setChildren(dto.getChildren().stream()
                    .map(this::convertDtoToVo)
                    .collect(Collectors.toList()));
        }
        return vo;
