    private String httpsRequest(String url, String xmlData) throws Exception {
        if (httpClient == null) {
            SSLContext sslcontext = SSLContexts.custom().loadTrustMaterial(null, new java.security.cert.X509TrustManager() {
                public java.security.cert.X509Certificate[] getAcceptedIssuers() { return null; }
                public void checkClientTrusted(java.security.cert.X509Certificate[] certs, String authType) {}
                public void checkServerTrusted(java.security.cert.X509Certificate[] certs, String authType) {}
            }).build();

            SSLConnectionSocketFactory sslsf = new SSLConnectionSocketFactory(sslcontext);
            httpClient = HttpClients.custom()
                    .setSSLSocketFactory(sslsf)
                    .setDefaultRequestConfig(RequestConfig.custom()
                            .setConnectTimeout(connectTimeout)
                            .setSocketTimeout(socketTimeout)
                            .build())
                    .build();
        }

        HttpPost httpPost = new HttpPost(url);
        httpPost.setEntity(new StringEntity(xmlData, "UTF-8"));
        HttpResponse response = httpClient.execute(httpPost);
        return EntityUtils.toString(response.getEntity(), "UTF-8");
    }
}
