    @Override
    public void restoreUrl(String shortUri, ServletRequest request, ServletResponse response) {
        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;
        String fullShortUrl = createShortLinkDefaultDomain + "/" + shortUri;
        String originUrl = stringRedisTemplate.opsForValue().get(String.format(GOTO_SHORT_LINK_KEY, fullShortUrl));
        if (StrUtil.isBlank(originUrl)) {
            ShortLinkGotoDO linkGotoDO = shortLinkGotoMapper.selectOne(Wrappers.lambdaQuery(ShortLinkGotoDO.class)
                    .eq(ShortLinkGotoDO::getFullShortUrl, fullShortUrl));
            if (linkGotoDO == null) {
                stringRedisTemplate.opsForValue().set(String.format(GOTO_IS_NULL_SHORT_LINK_KEY, fullShortUrl), "1", 10, TimeUnit.MINUTES);
                throw new ClientException("短链接不存在");
            }
            ShortLinkDO shortLinkDO = baseMapper.selectOne(Wrappers.lambdaQuery(ShortLinkDO.class)
                    .eq(ShortLinkDO::getFullShortUrl, fullShortUrl)
                    .eq(ShortLinkDO::getGid, linkGotoDO.getGid()));
            if (shortLinkDO == null) {
                throw new ServiceException("短链接数据异常");
            }
            originUrl = shortLinkDO.getOriginUrl();
            stringRedisTemplate.opsForValue().set(String.format(GOTO_SHORT_LINK_KEY, fullShortUrl), originUrl, LinkUtil.getLinkCacheValidTime(shortLinkDO.getValidDate()), TimeUnit.MILLISECONDS);
        }
        // Statistics logic
        ShortLinkDO shortLinkDO = baseMapper.selectOne(Wrappers.lambdaQuery(ShortLinkDO.class).eq(ShortLinkDO::getFullShortUrl, fullShortUrl));
        ShortLinkStatsRecordDTO statsRecord = ShortLinkStatsRecordDTO.builder()
                .fullShortUrl(fullShortUrl)
                .remoteAddr(LinkUtil.getActualIp(httpRequest))
                .os(LinkUtil.getOs(httpRequest))
                .browser(LinkUtil.getBrowser(httpRequest))
                .device(LinkUtil.getDevice(httpRequest))
                .network(LinkUtil.getNetwork(httpRequest))
                .build();
        shortLinkStats(fullShortUrl, shortLinkDO.getGid(), statsRecord);
        httpResponse.sendRedirect(originUrl);
    }

